mapper.select:
SELECT COUNT(1) FROM t_seatunnel_web_job_definition d
LEFT JOIN t_seatunnel_web_job_instance i ON i.id = ( SELECT t1.id FROM t_seatunnel_web_job_instance t1 WHERE t1.job_definition_id = d.id ORDER BY t1.create_time DESC, t1.id DESC LIMIT 1 )
AND d.id = #{dto.id}
AND d.job_name LIKE CONCAT('%', #{dto.jobName}, '%')
AND d.create_time >= #{dto.createTimeStart}
AND d.create_time <= #{dto.createTimeEnd}
AND d.source_type = #{dto.sourceType}
AND d.sink_type = #{dto.sinkType}
AND ( CASE WHEN d.task_type IS NOT NULL THEN d.task_type WHEN UPPER(COALESCE(d.mode, '')) = 'FILE_SYNC' THEN 'FILE_TRANSFER' WHEN UPPER(COALESCE(d.job_type, '')) = 'STREAMING' THEN 'STREAM' WHEN UPPER(COALESCE(d.mode, '')) = 'GUIDE_SINGLE' AND UPPER(COALESCE(d.source_type, '')) IN ('WEB_UPLOAD', 'FILE_RESOURCE', 'LOCAL_FILE') THEN 'FILE_INGEST' ELSE 'BATCH' END ) = #{dto.taskType}
AND d.mode = #{dto.mode}
AND (d.mode IS NULL OR d.mode != #{dto.excludeMode})
AND d.source_table LIKE CONCAT('%', #{dto.sourceTable}, '%')
AND d.sink_table LIKE CONCAT('%', #{dto.sinkTable}, '%')
